'use client';

import { useActionState } from 'react';

type ContactFormState = {
  success?: boolean;
  error?: string;
};

function ContactFormClient({
  submitAction,
}: {
  submitAction: (prevState: ContactFormState | null, formData: FormData) => Promise<ContactFormState>;
}) {
  const [state, formAction, pending] = useActionState(submitAction, null);

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" required placeholder="Your name" />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" required placeholder="your@email.com" />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" required placeholder="Your message" rows={5} />
        </div>
        {state?.error && <p style={{ color: 'red' }}>{state.error}</p>}
        {state?.success && <p style={{ color: 'green' }}>Thank you! Your message has been sent.</p>}
        <button type="submit" disabled={pending}>
          {pending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  );
}

export default function ContactForm() {
  async function submitContactMessage(
    _prevState: ContactFormState | null,
    formData: FormData
  ): Promise<ContactFormState> {
    'use server';

    const name = formData.get('name')?.toString().trim();
    const email = formData.get('email')?.toString().trim();
    const message = formData.get('message')?.toString().trim();

    // JavaScript validation: check that all fields are provided
    if (!name || !email || !message) {
      return { error: 'All fields are required. Please provide your name, email, and message.' };
    }

    // Simulate saving the contact message (e.g., to a database)
    console.log('Contact message received:', { name, email, message });

    return { success: true };
  }

  return <ContactFormClient submitAction={submitContactMessage} />;
}

